import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import toast from "react-hot-toast";

const Add_delete = () => {
  const initialUser = {
    name: "",
    class1: "",
    roll: "",
  };

  const [user, setUser] = useState(initialUser);
  const navigate = useNavigate();

  const inputHandler = (e) => {
    const { name, value } = e.target;
    setUser({ ...user, [name]: value });
  };

  const submitForm = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post("http://localhost:8005/api/user", user);
       toas(response.data.message);
    setUser({ name: "", class1: "", roll: "" });
    } catch (error) {
      console.error(error);
      toast.error("Failed to add student");
    }
  };

  return (
    <div className="addUser">
      <Link to="/Teacherdashboard" className="btn btn-secondary">
        <i className="fa-solid fa-backward"></i> Back
      </Link>

      <h3>Add New Student</h3>
      <form className="addUserForm" onSubmit={submitForm}>
        <div className="inputGroup">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            autoComplete="off"
            placeholder="Enter name"
            onChange={inputHandler}
          />
        </div>

        <div className="inputGroup">
          <label htmlFor="class1">Class:</label>
          <input
            type="text"
            id="class1"
            name="class1"
            autoComplete="off"
            placeholder="Enter class"
            onChange={inputHandler}
          />
        </div>

        <div className="inputGroup">
          <label htmlFor="roll">Roll No:</label>
          <input
            type="text"
            id="roll"
            name="roll"
            autoComplete="off"
            placeholder="Enter roll number"
            onChange={inputHandler}
          />
        </div>

        <div className="inputGroup">
          <button type="submit" className="btn btn-primary">
            Submit
          </button>
        </div>
      </form>
    </div>
  );
};

export default Add_delete;
